+
+fn pick_open_anchor(
+    first: &[Point2],
+    d: Point2,
+    comp: &Region,
+    rest_reach: &Region,
+    passes: &[Vec<Point2>],
+    prefer_closest: bool,
+    max_hop: f64,
+) -> Option<usize> {
+    let interior = 1..first.len() - 1;
+    let clear = |pt: Point2| chord_clears(comp, d, pt) && !chord_hits_plan(d, pt, passes);
+    if !prefer_closest
+        && let Some(idx) = interior.clone().find(|&i| {
