+
+fn project_anchor(
+    a: Point2,
+    b: Point2,
+    d: Point2,
+    comp: &Region,
+    rest_reach: &Region,
+    passes: &[Vec<Point2>],
+) -> Option<Point2> {
+    let (dx, dy) = (b.x - a.x, b.y - a.y);
+    let dd = dx * dx + dy * dy;
+    if !(dd.is_finite() && dd > 0.0) {
